export interface Sample {
  id: string;
  name: string;
  /** Plain-language blurb. */
  about: string;
  fasta: string;
}

const INS =
  '';

const HBB =
  '';

const EGFP =
  '';

function wrap(seq: string, width = 60): string {
  const lines: string[] = [];
  for (let i = 0; i < seq.length; i += width) lines.push(seq.slice(i, i + width));
  return lines.join('\n');
}

/** Short, well-known coding sequences so the app plays something on first load. */
export const SAMPLES: Sample[] = [
  {
    id: 'ins',
    name: 'Insulin (human)',
    about:
      'The hormone that controls blood sugar. This is the coding sequence for preproinsulin: 333 bases that build a 110-amino-acid protein.',
    fasta: `>INS Homo sapiens insulin, coding sequence\n${wrap(INS)}`,
  },
  {
    id: 'hbb',
    name: 'Haemoglobin beta (human)',
    about:
      'Part of the protein that carries oxygen in red blood cells. A single A→T change in codon 7 (GAG→GTG) causes sickle-cell disease.',
    fasta: `>HBB Homo sapiens hemoglobin subunit beta, coding sequence\n${wrap(HBB)}`,
  },
  {
    id: 'egfp',
    name: 'Green fluorescent protein',
    about:
      'EGFP, a brighter lab version of the jellyfish protein that glows green. It is widely used to light up cells under the microscope.',
    fasta: `>EGFP enhanced green fluorescent protein, coding sequence\n${wrap(EGFP)}`,
  },
];
